// Christmas Flash Sale — Festive Shopping Campaign
// Standalone pure Canvas 2D. Time is measured in SECONDS.
// Duration: 25 seconds. Scenes: 2. Design: 1920x1080, scalable to 4K.
// Recommended export: 3840x2160, 60 fps, 100,000,000 bits/s.
// Encoder bitrate is set in your video renderer, not in draw().
function draw(ctx, time, width, height) {
  const C = {
    "bg": "#F6F1E8",
    "bg2": "#EFE9DE",
    "paper": "#FFFBF3",
    "soft": "#E3E9DC",
    "accent": "#AF3545",
    "forest": "#244C40",
    "ink": "#213D34",
    "muted": "#6B746B",
    "line": "#D8DDCF",
    "gold": "#BE9B59",
    "ribbon": "#9B293B",
    "kraft": "#D5BA92"
  };
  const FOOTER = "FESTIVE GIFTS / SEASONAL OFFERS";
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  if (!ctx || !Number.isFinite(t) || t < 0 || width <= 0 || height <= 0) return;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const phase = (loopT / duration) * Math.PI * 2;
  const local = sceneProgress * sceneDuration;
  const FONT = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const wave = (cycles = 1, offset = 0) => Math.sin(phase * cycles + offset);

  function rr(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function rect(x, y, w, h, r, fill, stroke = null, lw = 2.5) {
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function polygon(points, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color = C.ink, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function grad(x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w * 0.3, y + h);
    g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function text(str, x, y, size, color = C.ink, weight = 600, maxWidth = 1600, align = 'left') {
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    const measured = ctx.measureText(str).width;
    if (measured > maxWidth) size *= maxWidth / measured;
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    ctx.textAlign = align; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    ctx.fillText(str, x, y);
  }
  function caps(str, x, y, size = 17, color = C.muted, maxWidth = 700, tracking = 2.0) {
    ctx.font = '700 ' + size + 'px ' + FONT;
    let total = ctx.measureText(str).width + tracking * Math.max(0, str.length - 1);
    if (total > maxWidth) { const f = maxWidth / total; size *= f; tracking *= f; }
    ctx.font = '700 ' + size + 'px ' + FONT;
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    let cursor = x;
    for (let i = 0; i < str.length; i++) {
      ctx.fillText(str[i], cursor, y); cursor += ctx.measureText(str[i]).width + tracking;
    }
  }
  function panel(x, y, w, h, color = C.paper, radius = 26, outline = C.line) {
    rect(x + 7, y + 10, w, h, radius, 'rgba(30,39,33,0.07)');
    rect(x, y, w, h, radius, color, outline, 2.2);
  }
  function place(x, y, angle, fn) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); fn(); ctx.restore();
  }
  function reveal(delay, fn, distance = 26) {
    const a = ease((local - delay) / 1.15);
    ctx.save(); ctx.globalAlpha *= a; ctx.translate(0, distance * (1 - a)); fn(); ctx.restore();
  }
  function chip(x, y, w, title, color = C.accent) {
    rect(x, y, w, 42, 21, C.soft);
    ellipse(x + 21, y + 21, 4, 4, color);
    caps(title, x + 36, y + 27, 15, color, w - 55, 1.4);
  }
  function star(x, y, r, color = C.accent, angle = 0, points = 4) {
    const vertices = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle - Math.PI / 2 + i * Math.PI / points;
      const rad = i % 2 === 0 ? r : r * (points === 4 ? 0.26 : 0.48);
      vertices.push([x + Math.cos(a) * rad, y + Math.sin(a) * rad]);
    }
    polygon(vertices, color);
  }
  function arrow(x, y, color = C.paper, size = 13) {
    line(x - size, y, x + size, y, color, 2.8);
    line(x + size - 8, y - 8, x + size, y, color, 2.8);
    line(x + size - 8, y + 8, x + size, y, color, 2.8);
  }
  function button(x, y, w, title, inverse = false) {
    const fill = inverse ? C.paper : C.accent;
    const ink = inverse ? C.ink : C.paper;
    rect(x + 4, y + 7, w, 76, 18, 'rgba(27,39,32,0.08)');
    rect(x, y, w, 76, 18, fill);
    text(title, x + 28, y + 47, 23, ink, 700, w - 100);
    arrow(x + w - 43 + 4 * wave(2, 0.3), y + 38, ink);
  }
  function check(x, y, radius = 18, fill = C.forest) {
    ellipse(x, y, radius, radius, fill);
    line(x - radius * 0.43, y, x - radius * 0.1, y + radius * 0.33, C.paper, 3);
    line(x - radius * 0.1, y + radius * 0.33, x + radius * 0.46, y - radius * 0.37, C.paper, 3);
  }
  function ornament(x, top, y, r, color = C.accent, angle = 0) {
    place(x, top, angle, () => {
      line(0, 0, 0, y - top - r - 10, C.line, 2);
      rect(-7, y - top - r - 10, 14, 10, 3, C.ink);
      ellipse(0, y - top, r, r, color, C.ink, 2.5);
      line(-r * 0.55, y - top - r * 0.36, r * 0.55, y - top - r * 0.36, C.paper, 3);
      line(-r * 0.73, y - top, r * 0.73, y - top, C.paper, 3);
      line(-r * 0.55, y - top + r * 0.36, r * 0.55, y - top + r * 0.36, C.paper, 3);
    });
  }
  function leaf(x, y, size = 30, angle = 0, color = C.forest) {
    place(x, y, angle, () => {
      ctx.beginPath(); ctx.moveTo(0, size * 0.65);
      ctx.bezierCurveTo(-size * 0.65, 0, -size * 0.42, -size * 0.75, 0, -size);
      ctx.bezierCurveTo(size * 0.5, -size * 0.62, size * 0.6, 0, 0, size * 0.65);
      ctx.closePath(); ctx.fillStyle = color; ctx.fill();
      line(0, size * 0.38, 0, -size * 0.65, C.paper, 1.7);
    });
  }
  function ground(x, y, w, color = C.line) { rect(x, y, w, 13, 6, color); }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent'; ctx.setLineDash([]);
  ctx.fillStyle = C.bg; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2); ctx.scale(scale, scale); ctx.translate(-960, -540);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.fillStyle = grad(0, 0, 1920, 1080, C.bg, C.bg2); ctx.fillRect(0, 0, 1920, 1080);

  // A very quiet printed backdrop. No blur, glow, bitmap or external asset.
  ctx.save(); ctx.globalAlpha = 0.54;
  ellipse(1415, 561, 373 + 3 * wave(1), 355, C.soft);
  ctx.restore();
  star(153, 94, 16, C.accent, 0, 4);
  caps('CHRISTMAS COLLECTION', 186, 102, 17, C.ink, 550, 2);
  text('THE HOLIDAY EDIT', 1778, 102, 17, C.muted, 600, 300, 'right');
  line(142, 145, 1778, 145, C.line, 1.7);

  function gift(x, y, w, h, body = C.accent, ribbon = C.paper) {
    const u = w / 200;
    rect(x + 6, y + 8, w, h, 10 * u, 'rgba(25,38,31,0.08)');
    rect(x, y, w, h, 10 * u, grad(x, y, w, h, body, body), C.ink, 2.6);
    rect(x + w * 0.425, y + 1, w * 0.15, h - 2, 0, ribbon);
    const center = x + w / 2;
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center - 60 * u, y - 27 * u, center - 74 * u, y - 88 * u, center - 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center - 6 * u, y - 49 * u, center - 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fillStyle = ribbon; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.4; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center + 60 * u, y - 27 * u, center + 74 * u, y - 88 * u, center + 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center + 6 * u, y - 49 * u, center + 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    rect(x - 6 * u, y - 20 * u, w + 12 * u, 27 * u, 6 * u, body, C.ink, 2.6);
    rect(center - w * 0.075, y - 19 * u, w * 0.15, 25 * u, 0, ribbon);
    ellipse(center, y - 29 * u, 11 * u, 10 * u, ribbon, C.ink, 2.2);
  }

  function bag(x, y, w, h, body = C.forest, ribbon = C.paper) {
    const u = w / 180;
    ctx.beginPath(); ctx.moveTo(x + w * 0.3, y + 8);
    ctx.lineTo(x + w * 0.3, y - 29 * u);
    ctx.bezierCurveTo(x + w * 0.3, y - 78 * u, x + w * 0.7, y - 78 * u, x + w * 0.7, y - 29 * u);
    ctx.lineTo(x + w * 0.7, y + 8);
    ctx.strokeStyle = C.ink; ctx.lineWidth = 7 * u; ctx.stroke();
    polygon([[x + 10, y], [x + w - 10, y], [x + w, y + h], [x, y + h]], body, C.ink, 2.8);
    polygon([[x + w - 25, y + 8], [x + w - 10, y + 8], [x + w - 1, y + h - 4], [x + w - 25, y + h - 4]], 'rgba(23,39,32,0.10)');
    rect(x + w * 0.445, y + 2, w * 0.11, h - 4, 0, ribbon);
    ellipse(x + w / 2, y + h * 0.5, w * 0.18, w * 0.18, body);
    star(x + w / 2, y + h * 0.5, w * 0.13, ribbon, 0, 5);
  }

  function headphones(x, y, s = 1) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath(); ctx.moveTo(-68, 14); ctx.lineTo(-68, -38);
    ctx.bezierCurveTo(-68, -139, 68, -139, 68, -38); ctx.lineTo(68, 14);
    ctx.strokeStyle = C.ink; ctx.lineWidth = 19; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-68, -34); ctx.bezierCurveTo(-68, -125, 68, -125, 68, -34);
    ctx.strokeStyle = C.forest; ctx.lineWidth = 10; ctx.stroke();
    rect(-93, -16, 43, 96, 17, C.accent, C.ink, 2.8);
    rect(50, -16, 43, 96, 17, C.accent, C.ink, 2.8);
    rect(-57, -8, 16, 80, 7, C.ink);
    rect(41, -8, 16, 80, 7, C.ink);
    for (let i = 0; i < 4; i++) {
      line(-80, 10 + i * 14, -66, 10 + i * 14, C.paper, 2);
      line(66, 10 + i * 14, 80, 10 + i * 14, C.paper, 2);
    }
    ctx.restore();
  }

  function mug(x, y, s = 1, steam = false) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ellipse(82, 2, 33, 37, C.paper, C.ink, 3);
    ellipse(83, 2, 18, 23, C.soft, C.ink, 2.5);
    ellipse(5, 90, 93, 11, C.line);
    ctx.beginPath(); ctx.moveTo(-58, -49); ctx.lineTo(-50, 66);
    ctx.quadraticCurveTo(-48, 82, 0, 82); ctx.quadraticCurveTo(48, 82, 50, 66);
    ctx.lineTo(58, -49); ctx.closePath(); ctx.fillStyle = grad(-60, -50, 120, 130, C.paper, C.soft); ctx.fill();
    ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.stroke();
    ellipse(0, -49, 58, 12, C.paper, C.ink, 2.6);
    ellipse(0, -48, 49, 7, '#614737');
    star(0, 18, 22, C.accent, 0, 5);
    if (steam) {
      for (let i = 0; i < 2; i++) {
        const shift = 4 * wave(2, i * 1.4);
        ctx.beginPath(); ctx.moveTo(-19 + i * 38, -73);
        ctx.bezierCurveTo(-37 + i * 38 + shift, -91, -3 + i * 38 + shift, -106, -18 + i * 38, -128);
        ctx.strokeStyle = C.muted; ctx.lineWidth = 2.6; ctx.stroke();
      }
    }
    ctx.restore();
  }

  if (currentScene === 0) {
    reveal(0.12, () => chip(142, 230, 279, 'THE FESTIVE SELECTION'));
    reveal(0.22, () => {
      text('Christmas', 142, 410, 99, C.ink, 700, 670);
      text('SALE', 135, 559, 158, C.accent, 800, 690);
      text('Good gifts. Better prices.', 146, 626, 30, C.ink, 600, 650);
      text('A festive selection for every wish list.', 146, 674, 24, C.muted, 500, 650);
    });
    reveal(0.4, () => button(146, 731, 332, 'EXPLORE GIFTS'));
    reveal(0.55, () => {
      star(160, 866, 11, C.accent, 0, 5); text('Curated gifts', 184, 873, 20, C.muted, 600, 210);
      check(426, 866, 12); text('Seasonal offers', 451, 873, 20, C.muted, 600, 250);
    });
    reveal(0.2, () => place(1055, 535 + 4 * wave(1, 0.4), -0.022 + 0.004 * wave(1), () => {
      panel(-180, -235, 360, 470);
      caps('01 / AUDIO', -153, -199, 13, C.muted, 200, 1.4);
      rect(-153, -177, 306, 287, 19, C.soft);
      headphones(0, -20, 1.25);
      text('AUDIO ESSENTIALS', -150, 161, 23, C.ink, 700, 297);
      text('A little joy, every day.', -150, 198, 18, C.muted, 500, 297);
    }));
    reveal(0.38, () => place(1496, 442 + 4 * wave(1, 1.6), 0.021 + 0.003 * wave(1, 0.8), () => {
      panel(-188, -194, 376, 388);
      caps('02 / COZY', -160, -156, 13, C.muted, 200, 1.4);
      rect(-160, -137, 320, 237, 18, '#F2DDD5');
      mug(-15, -22, 0.93);
      text('COZY FAVOURITES', -159, 144, 23, C.ink, 700, 317);
      text('Made for warm moments.', -159, 177, 18, C.muted, 500, 317);
    }));
    reveal(0.58, () => place(1496, 797 + 3 * wave(1, 2.6), 0, () => {
      panel(-188, -104, 376, 208, C.paper);
      bag(-142, -33, 92, 106, C.forest, C.paper);
      text('GIFT-READY', -15, -7, 23, C.ink, 700, 170);
      text('Wrapped with care.', -15, 27, 18, C.muted, 500, 171);
      line(-15, 53, 124, 53, C.line, 2);
    }));
    reveal(0.68, () => {
      gift(898, 870 + 2.5 * wave(2), 142, 61, C.accent, C.paper);
      gift(1087, 875 + 2.5 * wave(2, 1.2), 132, 55, C.forest, C.gold);
    });
    star(865, 228 + 4 * wave(1), 18, C.gold, 0.1 + 0.025 * wave(1), 4);
    ornament(1760, 175, 297, 25, C.accent, 0.009 * wave(1));
    star(1765, 704 + 3 * wave(2), 16, C.forest, 0, 4);
  } else {
    reveal(0.14, () => {
      panel(142, 232, 926, 636, C.forest, 32, C.forest);
      caps('LIMITED HOLIDAY OFFER', 206, 304, 19, C.paper, 750, 2.5);
      text('UP TO', 206, 373, 34, C.paper, 600, 300);
      text('30%', 194, 626, 250, C.paper, 800, 561);
      text('OFF', 801, 555, 77, C.paper, 700, 202);
      line(207, 651, 998, 651, 'rgba(248,244,234,0.30)', 1.8);
      text('Christmas favourites, thoughtfully priced.', 207, 707, 27, C.paper, 500, 790);
      button(207, 749, 343, 'SHOP NOW', true);
      caps('THE FESTIVE EDIT', 626, 795, 17, C.paper, 350, 1.7);
    });
    reveal(0.35, () => place(1260, 381, 0.016 * wave(1, 0.8), () => {
      line(0, -145, 0, -22, C.line, 2);
      polygon([[-77, 12], [-20, -28], [20, -28], [77, 12], [77, 156], [-77, 156]], C.accent, C.ink, 2.7);
      ellipse(0, -6, 6, 6, C.paper);
      text('HOLIDAY', 0, 59, 20, C.paper, 700, 136, 'center');
      text('SAVINGS', 0, 92, 20, C.paper, 700, 136, 'center');
      star(0, 125, 13, C.gold, 0, 4);
    }));
    reveal(0.38, () => {
      bag(1433, 358 + 4 * wave(1, 0.5), 237, 268, C.paper, C.accent);
      ground(1415, 651, 271);
    });
    reveal(0.62, () => {
      gift(1184, 741 + 3 * wave(2, 1), 226, 143, C.accent, C.paper);
      gift(1487, 744 + 3 * wave(2, 2.6), 226, 140, C.forest, C.gold);
      ground(1164, 905, 268); ground(1468, 905, 268);
    });
    star(1760, 637 + 3 * wave(1), 19, C.gold, 0.02 * wave(1), 4);
    ornament(1754, 176, 281, 25, C.accent, 0.009 * wave(1));
    star(1365, 209 + 2 * wave(1, 2), 17, C.forest, 0, 4);
  }

  line(142, 961, 1778, 961, C.line, 1.7);
  caps(FOOTER, 142, 1009, 15, C.muted, 1100, 1.8);
  rect(1620, 996, 62, 6, 3, currentScene === 0 ? C.accent : C.line);
  rect(1698, 996, 62, 6, 3, currentScene === 1 ? C.accent : C.line);

  // The scene changes only behind a completely opaque wrapping-paper wipe.
  // Opening and closing use a C2-continuous quintic curve, with identical
  // pixels at 0 and 25 seconds. Pattern drift is also exactly 25s periodic.
  const wipeDuration = 1.45;
  const closeStart = sceneDuration - wipeDuration;
  if (local < wipeDuration || local > closeStart) {
    const opening = local < wipeDuration;
    const progress = opening ? ease(local / wipeDuration) : ease((local - closeStart) / wipeDuration);
    const left = opening ? 1920 * progress : 0;
    const right = opening ? 1920 : 1920 * progress;
    ctx.save(); ctx.beginPath(); ctx.rect(left, 0, Math.max(0, right - left), 1080); ctx.clip();
    ctx.fillStyle = C.accent; ctx.fillRect(0, 0, 1920, 1080);
    const drift = 28 * wave(1);
    for (let i = -2; i < 5; i++) {
      const x = i * 580 + drift;
      polygon([[x, -100], [x + 76, -100], [x + 655, 1180], [x + 579, 1180]], C.ribbon);
    }
    ctx.restore();
  }
  ctx.restore();
}

// Christmas Gift Guide — Find Their Perfect Gift
// Standalone pure Canvas 2D. Time is measured in SECONDS.
// Duration: 25 seconds. Scenes: 2. Design: 1920x1080, scalable to 4K.
// Recommended export: 3840x2160, 60 fps, 100,000,000 bits/s.
// Encoder bitrate is set in your video renderer, not in draw().
function draw(ctx, time, width, height) {
  const C = {
    "bg": "#F5F1E8",
    "bg2": "#EFEADC",
    "paper": "#FFFCF4",
    "soft": "#E3EADC",
    "accent": "#BC675D",
    "forest": "#526C50",
    "ink": "#293E31",
    "muted": "#737C6D",
    "line": "#D4DDCC",
    "gold": "#BAA060",
    "ribbon": "#A85950",
    "kraft": "#D5BA92"
  };
  const FOOTER = "CURATED GIFTS / THOUGHTFUL MOMENTS";
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  if (!ctx || !Number.isFinite(t) || t < 0 || width <= 0 || height <= 0) return;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const phase = (loopT / duration) * Math.PI * 2;
  const local = sceneProgress * sceneDuration;
  const FONT = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const wave = (cycles = 1, offset = 0) => Math.sin(phase * cycles + offset);

  function rr(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
