// Encoder bitrate is set in your video renderer, not in draw().
function draw(ctx, time, width, height) {
  const C = {
    "bg": "#EDF3EB",
    "bg2": "#E1EADC",
    "paper": "#FFFBED",
    "soft": "#DCE8D7",
    "accent": "#A84746",
    "forest": "#28564E",
    "ink": "#25443C",
    "muted": "#697B70",
    "line": "#CAD8C6",
    "gold": "#BFA058",
    "ribbon": "#8E393B",
    "kraft": "#D5BA92"
  };
  const FOOTER = "MUSIC / MOMENTS / CHRISTMAS MEMORIES";
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
